533|int
534|md_html(const MD_CHAR* input, MD_SIZE input_size,
535|        void (*process_output)(const MD_CHAR*, MD_SIZE, void*),
536|        void* userdata, unsigned parser_flags, unsigned renderer_flags)
537|{
538|    MD_HTML render = { process_output, userdata, renderer_flags, 0, { 0 } };
539|    int i;
540|
541|    MD_PARSER parser = {
542|        0,
543|        parser_flags,
544|        enter_block_callback,
545|        leave_block_callback,
546|        enter_span_callback,
547|        leave_span_callback,
548|        text_callback,
549|        debug_log_callback,
550|        NULL
551|    };
552|
553|    /* Build map of characters which need escaping. */
554|    for(i = 0; i < 256; i++) {
555|        unsigned char ch = (unsigned char) i;
556|
557|        if(strchr("\"&<>", ch) != NULL)
558|            render.escape_map[i] |= NEED_HTML_ESC_FLAG;
559|
560|        if(!ISALNUM(ch)  &&  strchr("~-_.+!*(),%#@?=;:/,+$", ch) == NULL)
561|            render.escape_map[i] |= NEED_URL_ESC_FLAG;
562|    }
563|
564|    /* Consider skipping UTF-8 byte order mark (BOM). */
565|    if(renderer_flags & MD_HTML_FLAG_SKIP_UTF8_BOM  &&  sizeof(MD_CHAR) == 1) {
566|        static const MD_CHAR bom[3] = { (char)0xef, (char)0xbb, (char)0xbf };
567|        if(input_size >= sizeof(bom)  &&  memcmp(input, bom, sizeof(bom)) == 0) {
568|            input += sizeof(bom);
569|            input_size -= sizeof(bom);
570|        }
571|    }
572|
573|    return md_parse(input, input_size, &parser, (void*) &render);
574|}

